package cn.shanhai.game;
import android.app.*;import android.os.*;import android.view.*;import android.graphics.*;import android.media.*;import android.content.*;import android.content.res.AssetFileDescriptor;import java.io.*;import java.util.*;
public class MainActivity extends Activity implements Board.Host {
 Board board;Table view;MediaPlayer music;SoundPool sounds;HashMap<String,Integer> sfx=new HashMap<>();boolean active=false,loaded=false;long lastAI=0;Engine counted=null;
 AudioManager manager;boolean focus=true;
 final AudioManager.OnAudioFocusChangeListener focusListener=new AudioManager.OnAudioFocusChangeListener(){public void onAudioFocusChange(int value){focus=value==AudioManager.AUDIOFOCUS_GAIN;if(music!=null){if(focus&&active&&board.music)music.start();else if(music.isPlaying())music.pause();}}};
 final Handler handler=new Handler();final Runnable pulse=new Runnable(){public void run(){if(active){if(board.game!=null&&board.screen.equals("battle")&&board.modal.isEmpty()){Engine e=board.game;boolean busy=board.tick();int delay=board.speed==0?1100:board.speed==1?650:300;
 if(!busy&&e.phase!=3&&System.currentTimeMillis()-lastAI>delay&&(e.phase==1?(e.responder()!=0||board.auto):(e.turn!=0||board.auto))){if(e.phase==1&&e.responder()==0&&board.auto)e.response(e.count(0,e.required())>0);else e.ai();lastAI=System.currentTimeMillis();board.selected=-1;save();}
 if(e.phase==3&&counted!=e){board.played++;if(e.winner==0)board.wins++;counted=e;save();sound(e.winner==0?"win":"fall");}}view.invalidate();handler.postDelayed(this,33);}}};

 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);getWindow().getDecorView().setSystemUiVisibility(5894);board=new Board(this);load();view=new Table(this);setContentView(view);sounds=new SoundPool.Builder().setMaxStreams(5).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).build()).build();for(String id:new String[]{"tap","select","error","cast","guard","hit","win","slash","heal","storm","equip","draw","skill","turn","fall"})try{AssetFileDescriptor fd=getAssets().openFd("audio/"+id+".wav");sfx.put(id,sounds.load(fd,1));fd.close();}catch(Exception ex){android.util.Log.w("Shanhai","sound",ex);}try{music=new MediaPlayer();AssetFileDescriptor fd=getAssets().openFd("audio/mountains.ogg");music.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());fd.close();music.setLooping(true);music.setVolume(board.musicVol/8f*.6f,board.musicVol/8f*.6f);music.prepare();}catch(Exception ex){android.util.Log.w("Shanhai","music",ex);}manager=(AudioManager)getSystemService(AUDIO_SERVICE);manager.requestAudioFocus(focusListener,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN);loaded=true;}
 @Override protected void onResume(){super.onResume();active=true;lastAI=System.currentTimeMillis();if(music!=null&&board.music&&focus)music.start();handler.removeCallbacks(pulse);handler.post(pulse);}
 @Override protected void onPause(){super.onPause();active=false;handler.removeCallbacks(pulse);if(music!=null&&music.isPlaying())music.pause();save();}
 @Override protected void onDestroy(){super.onDestroy();if(music!=null)music.release();if(sounds!=null)sounds.release();if(manager!=null)manager.abandonAudioFocus(focusListener);}
 @Override public void onBackPressed(){if(!board.modal.isEmpty())board.modal="";else if(board.screen.equals("battle")){board.modal="pause";save();}else if(!board.screen.equals("home"))board.screen="home";else new AlertDialog.Builder(this).setTitle("离开山海？").setMessage("对局进度已保存。").setPositiveButton("离开",new android.content.DialogInterface.OnClickListener(){public void onClick(android.content.DialogInterface d,int w){finish();}}).setNegativeButton("留下",null).show();view.invalidate();}
 public void sound(String id){if(board.sound&&sounds!=null&&sfx.containsKey(id))sounds.play(sfx.get(id),board.soundVol/8f,board.soundVol/8f,1,0,1);}
 public void settings(){if(music!=null){music.setVolume(board.musicVol/8f*.6f,board.musicVol/8f*.6f);if(board.music&&active&&focus)music.start();else if(music.isPlaying())music.pause();}save();}
 public void save(){if(board==null)return;getPreferences(0).edit().putBoolean("music",board.music).putBoolean("sound",board.sound).putBoolean("motion",board.motion).putInt("musicVol",board.musicVol).putInt("soundVol",board.soundVol).putInt("speed",board.speed).putInt("hero",board.chosen).putInt("played",board.played).putInt("wins",board.wins).apply();if(board.game!=null)try{File tmp=new File(getFilesDir(),"match.tmp");ObjectOutputStream out=new ObjectOutputStream(new FileOutputStream(tmp));out.writeObject(board.game);out.close();File dest=new File(getFilesDir(),"match.bin");if(!tmp.renameTo(dest))android.util.Log.e("Shanhai","Could not commit save");}catch(Exception ex){android.util.Log.e("Shanhai","save failed",ex);}}
 void load(){android.content.SharedPreferences p=getPreferences(0);board.music=p.getBoolean("music",true);board.sound=p.getBoolean("sound",true);board.motion=p.getBoolean("motion",true);board.musicVol=p.getInt("musicVol",3);board.soundVol=p.getInt("soundVol",6);board.speed=p.getInt("speed",1);board.chosen=p.getInt("hero",0);board.played=p.getInt("played",0);board.wins=p.getInt("wins",0);try{ObjectInputStream in=new ObjectInputStream(new FileInputStream(new File(getFilesDir(),"match.bin")));board.game=(Engine)in.readObject();in.close();if(board.game.phase==3)counted=board.game;}catch(Exception ex){board.game=null;}}
 class Table extends View implements Board.Ink {
 Canvas canvas;Paint p=new Paint(3);HashMap<String,Bitmap> arts=new HashMap<>();Typeface normal=Typeface.create("sans-serif",0),serif;float scale,ox,oy;float touchX,touchY;
 Table(Context c){super(c);setFocusable(true);setContentDescription("山海同契，横屏策略卡牌对局");try{serif=Typeface.createFromAsset(getAssets(),"serif.otf");}catch(Exception ex){serif=Typeface.create("serif",0);}for(String id:new String[]{"qingqiu","yinglong","jingwei","zhuyin","table"})try{BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=2;arts.put(id,BitmapFactory.decodeStream(getAssets().open("art/"+id+".jpg"),null,options));}catch(Exception ex){android.util.Log.e("Shanhai","art missing",ex);}}
 protected void onDraw(Canvas c){canvas=c;c.drawColor(Board.BG);scale=Math.min(getWidth()/1280f,getHeight()/720f);ox=(getWidth()-1280*scale)/2;oy=(getHeight()-720*scale)/2;c.save();c.translate(ox,oy);c.scale(scale,scale);board.render(this);c.restore();}
 boolean holding=false;final Runnable hold=new Runnable(){public void run(){holding=true;board.longPress((touchX-ox)/scale,(touchY-oy)/scale);invalidate();}};
 public boolean onTouchEvent(android.view.MotionEvent e){int action=e.getAction();if(action==MotionEvent.ACTION_DOWN){touchX=e.getX();touchY=e.getY();holding=false;board.press((touchX-ox)/scale,(touchY-oy)/scale);handler.postDelayed(hold,520);invalidate();return true;}if(action==MotionEvent.ACTION_MOVE&&Math.hypot(e.getX()-touchX,e.getY()-touchY)>25){handler.removeCallbacks(hold);board.pressed="";}
 if(action==MotionEvent.ACTION_UP){handler.removeCallbacks(hold);if(!holding&&Math.abs(touchX-e.getX())<50&&Math.abs(touchY-e.getY())<50){board.tap((e.getX()-ox)/scale,(e.getY()-oy)/scale);lastAI=System.currentTimeMillis();performClick();}board.pressed="";invalidate();return true;}if(action==MotionEvent.ACTION_CANCEL){handler.removeCallbacks(hold);board.pressed="";invalidate();}return true;}

 public boolean performClick(){super.performClick();return true;}
 public void poly(float[] pts,int color){Path path=new Path();path.moveTo(pts[0],pts[1]);for(int i=2;i<pts.length;i+=2)path.lineTo(pts[i],pts[i+1]);path.close();p.setColor(color);p.setStyle(Paint.Style.FILL);canvas.drawPath(path,p);}
 public void rect(float x,float y,float w,float h,int color,float radius){p.setColor(color);p.setStyle(Paint.Style.FILL);canvas.drawRoundRect(x,y,x+w,y+h,radius,radius,p);}
 public void line(float x,float y,float x2,float y2,int color,float width){p.setColor(color);p.setStrokeWidth(width);canvas.drawLine(x,y,x2,y2,p);}
 public void circle(float x,float y,float r,int color){p.setColor(color);canvas.drawCircle(x,y,r,p);}
 public void text(String s,float x,float y,float size,int color,boolean ser){p.setColor(color);p.setTextSize(size);p.setTypeface(ser?serif:normal);canvas.drawText(s,x,y,p);}
 public void art(String id,float x,float y,float w,float h,int alpha){Bitmap b=arts.get(id);if(b==null)return;float factor=Math.max(w/b.getWidth(),h/b.getHeight());int sw=Math.min(b.getWidth(),(int)(w/factor)),sh=Math.min(b.getHeight(),(int)(h/factor));int sx=(b.getWidth()-sw)/2;Rect src=new Rect(sx,0,sx+sw,sh);p.setAlpha(alpha);canvas.drawBitmap(b,src,new RectF(x,y,x+w,y+h),p);p.setAlpha(255);}
 }
}
